/**
 * The mixer: the one gate every sound effect and music track plays through,
 * and the keys and URLs of the audio files. Pure: no Phaser or DOM. The
 * prototype had no mixer; here it is two on/off switches in the per-machine
 * settings (settings.ts), not volumes. The files live under
 * public/assets/audio/ and are all WAV: the build has no Ogg encoder and WAV
 * decodes everywhere. The sound effects (7-b) are short WAVs generated by
 * art/sounds.mjs; the music (7-c) is one short seamless loop per place,
 * generated by art/music.mjs at 11025 Hz to keep the files small.
 */

import type { RoomKey } from '../world/shedRoom';
import type { Settings } from './settings';

/** A sound effect or a music track; each has its own switch. */
export type AudioKind = 'sound' | 'music';

/** Whether a play call of `kind` may make a sound: `settings.sound` for effects, `settings.music` for music. */
export function audioAllowed(settings: Settings, kind: AudioKind): boolean {
  return kind === 'sound' ? settings.sound : settings.music;
}

/** The sound effects 7-b brings, by file name. */
export const SOUND_KEYS = ['water', 'snip', 'wire', 'footstep', 'click', 'door', 'coin'] as const;
export type SoundKey = (typeof SOUND_KEYS)[number];

/** The music tracks 7-c brings, by file name: one loop per place, the house's three rooms sharing one and the greenhouse the garden's. */
export const MUSIC_KEYS = ['shed', 'garden', 'house', 'viewer'] as const;
export type MusicKey = (typeof MUSIC_KEYS)[number];

/** Where music can play: a room, or the 3D viewer over it. */
export type MusicPlace = RoomKey | 'viewer';

const TRACKS: Record<MusicPlace, MusicKey> = {
  shed: 'shed',
  garden: 'garden',
  lounge: 'house',
  hallway: 'house',
  study: 'house',
  greenhouse: 'garden',
  viewer: 'viewer',
};

/** The loop that plays in `place`. */
export function trackFor(place: MusicPlace): MusicKey {
  return TRACKS[place];
}

/** How long one loop takes to cross-fade into the next, in ms: a room change, or the viewer opening or closing. */
export const MUSIC_FADE_MS = 1200;

/** The music's volume under the effects (which play at 1), as Phaser's 0..1. */
export const MUSIC_VOLUME = 0.4;

/** The file's URL under the app's base path (`import.meta.env.BASE_URL`, which ends in `/`). */
export function audioUrl(base: string, key: SoundKey | MusicKey): string {
  return `${base}assets/audio/${key}.wav`;
}
